require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/auth.php'; require_login();
$stats=['total'=>0,'dirty'=>0,'blocked'=>0,'clean'=>0,'resolved'=>0,'pending'=>0]; $recent=[]; $monthly=[];
try {
 $uid=current_user_id();
 $q=db()->prepare("SELECT COUNT(*) total, SUM(category='dirty') dirty, SUM(category='blocked') blocked, SUM(category='clean') clean, SUM(status='Resolved') resolved, SUM(status='Pending') pending FROM reports WHERE user_id=?");$q->execute([$uid]);$stats=array_merge($stats,$q->fetch()?:[]);
 $q=db()->prepare('SELECT id,title,category,location_name,status,created_at,photo_path FROM reports WHERE user_id=? ORDER BY created_at DESC LIMIT 6');$q->execute([$uid]);$recent=$q->fetchAll();
 $q=db()->prepare("SELECT DATE_FORMAT(created_at,'%Y-%m') month, COUNT(*) total FROM reports WHERE user_id=? AND created_at >= DATE_SUB(CURDATE(), INTERVAL 6 MONTH) GROUP BY month ORDER BY month");$q->execute([$uid]);$monthly=$q->fetchAll();
} catch(Throwable $e){error_log($e->getMessage());}
$page_title='Dashboard'; require 'includes/header.php'; require 'includes/sidebar.php';
